import csv, sys
csv.field_size_limit(sys.maxsize)

def read_csv(path):
    rows, index = [], {}
    with open(path, 'r', newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        fn = list(reader.fieldnames) if reader.fieldnames else []
        while True:
            try:
                row = next(reader)
                act = (row.get('act') or '').strip()
                if act:
                    index[act] = len(rows)
                    rows.append(row)
            except csv.Error:
                pass
            except StopIteration:
                break
    return rows, index, fn

def normalize(s):
    return (s or '').replace('\r\n', '\n').replace('\r', '\n').strip()

def make_email(name):
    if '@' in name:
        return name
    return f'{name}@users.noreply.github.com'

def parse_contributors(field):
    if not field:
        return 'anonymous', []
    parts = [c.strip() for c in field.split(',') if c.strip()]
    if not parts:
        return 'anonymous', []
    return parts[0], parts[1:]

